export type BuildAppOptions = {
  startWorkers?: boolean;
  startScheduler?: boolean;
  pillowEnabled?: boolean;
  /** Production: listen before registering hundreds of REAL module routes. */
  earlyListen?: boolean;
};

export type EmpireApp = {
  app: FastifyInstance;
  brain: EmpireBrain;
  shutdown: () => Promise<void>;
  /** Candidate in-process HTTP boundary only. The caller must also fence
   * workers, all stores, Redis and other processes before any capture claim.
   */
  withDrainedHttpAdmission: <T>(capture: () => T | Promise<T>, timeoutMs?: number) => Promise<T>;
  /** Candidate local HTTP + Brain worker + Pillow boot + authority JSON boundary; external workers,
   * schedulers, stores and Redis remain independent.
   */
  withDrainedLocalAdmission: <T>(capture: () => T | Promise<T>, timeoutMs?: number) => Promise<T>;
  /** Candidate local SQL.js RAM save inside the local admission and JSON fence.
   * The supplied Shadow handle must be the one used by writers; other handles,
   * processes, native stores and Redis still require independent quiescence.
   */
  withDrainedLocalSqliteCapture: <T>(shadow: SqliteShadowCeoRepository,
    captureAndVerify: () => T | Promise<T>, timeoutMs?: number) => Promise<T>;
  /** Additionally fence the existing native mission and execution sidecars.
   * Redis, other replicas and separately opened Shadow handles remain outside.
   */
  withDrainedLocalNativeCapture: <T>(shadow: SqliteShadowCeoRepository,
    captureAndVerify: () => T | Promise<T>, timeoutMs?: number) => Promise<T>;
  /** Global BullMQ consumer pause and drain plus local native/SQL.js capture.
   * Repeat producers, new Redis jobs and other store handles still need fences.
   * Refuses degraded Redis; never use on the protected old deployment.
   */
  withDrainedSharedBrainNativeCapture: <T>(shadow: SqliteShadowCeoRepository,
    captureAndVerify: () => T | Promise<T>, timeoutMs?: number) => Promise<T>;
  /** Also drains the registered local intelligence, commerce, twin and Assurance timers.
   * Also holds nine domain SQLite writer locks. Other processes and Redis producers
   * remain outside; WAL domains require SQLite-aware capture, not raw main-file copies.
   */
  withDrainedWork8LocalCapture: <T>(shadow: SqliteShadowCeoRepository,
    captureAndVerify: () => T | Promise<T>, timeoutMs?: number) => Promise<T>;
  captureWork8Recovery: (request:Work8RecoveryRequest,scope?:GeneratedCaptureScope)=>Promise<Work8RecoveryResult>;
  finishRouteRegistration?: () => Promise<void>;
};

export async function buildApp(options: BuildAppOptions = {}): Promise<EmpireApp> {
  const { startWorkers, startScheduler, commerceAutomation } = backgroundExecutionPolicy(options);
  const pillowEnabled = options.pillowEnabled ?? true;
  const earlyListen = options.earlyListen ?? false;

  const brain = await createBrain({ startWorkers, startScheduler });
  await seedDefaultUsers();

  let deferredBootstrap: ReturnType<typeof setImmediate> | undefined;
  let stopping = false;
  const deferHeavyBootstrap = env.NODE_ENV === "production";
  if (deferHeavyBootstrap) {
    deferredBootstrap = setImmediate(() => {
      if (stopping) return;
      try {
        const ran=runLegacyBusinessBootstrap(()=>{
          seedDomainData();
          seedGrandKingAccount();
          bootstrapFoundation("ws_empire_1");
        });
        logger.info(ran ? "Deferred production bootstrap completed" : "Legacy business fixture bootstrap skipped for explicit runtime profile");
      } catch (error) {
        logger.error(
          { error: error instanceof Error ? error.message : String(error) },
          "Deferred production bootstrap failed",
        );
      }
    });
  } else {
    runLegacyBusinessBootstrap(()=>{
      seedDomainData();
      seedGrandKingAccount();
      bootstrapFoundation("ws_empire_1");
    });
  }

  const pillowHost = getPillowHost();
  const pillowBootTask = new ManagedBackgroundTask({
    run: async () => {
      await schedulePillowHostBoot(pillowHost, brain.llmRouter, brain.auditLogger);
      if (!stopping) syncPresaleApprovalGateWithPillowHost(pillowHost);
    },
    onError: (error) => logger.error(
      { error: error instanceof Error ? error.message : String(error) },
      "Pillow host startup failed — backend continues in degraded mode",
    ),
  });
  if (pillowEnabled) pillowBootTask.start(env.NODE_ENV === "production" ? 15_000 : 5_000);
  const stopBackgroundWork = async () => {
    stopping = true;
    clearImmediate(deferredBootstrap);
    await Promise.all([
      pillowBootTask.stop(),
      getPillowCommercePresaleAutomationServer().stop(),
      getPillowExecutiveLoopAutomationServer().stop(),
    ]);
  };

  const sessionStore = brain.sessionStore;
  const authenticate = createAuthMiddleware(sessionStore);
  const eventStream = new EventStreamHub(brain.eventBus);
  eventStream.start();

  const app = Fastify({ logger: false });
  installLockedCommissioning(app);

  await app.register(cors, {
    origin: env.CORS_ORIGIN,
    credentials: true,
  });

  await app.register(cookie, {
    secret: env.SESSION_SECRET,
  });
  const captureHttpAdmission = installCaptureHttpAdmission(app);

  app.addHook("onRequest", async (request) => {
    (request as typeof request & { startTime: number }).startTime = Date.now();
  });

  app.addHook("onResponse", async (request, reply) => {
    const startTime = (request as typeof request & { startTime?: number }).startTime;
    recordRequest({
      path: request.url,
      method: request.method,
      statusCode: reply.statusCode,
      durationMs: startTime ? Date.now() - startTime : 0,
    });
  });

  app.setErrorHandler((error, request, reply) => {
    const err = error instanceof Error ? error : new Error(String(error));
    const statusFromError =
      typeof error === "object" &&
      error !== null &&
      "statusCode" in error &&
      typeof (error as { statusCode?: unknown }).statusCode === "number"
        ? (error as { statusCode: number }).statusCode
        : undefined;

    logger.error(
      {
        error: err.message,
        stack: err.stack,
        path: request.url,
        method: request.method,
      },
      "Request failed",
    );

    if (error instanceof SessionStoreUnavailableError) {
      return reply.code(503).send({
        error: "Shared session store temporarily unavailable",
        code: "SHARED_SESSION_STORE_UNAVAILABLE",
        retryable: true,
      });
    }

    if (error instanceof z.ZodError) {
      return reply.code(400).send({
        error: "Validation failed",
        details: error.flatten(),
      });
    }

    if (error instanceof GuardianBlockedError) {
      return reply.code(403).send({
        error: error.message,
        guardian: error.verdict,
      });
    }

    if (error instanceof GovernanceBlockedError) {
      return reply.code(403).send({
        error: error.message,
        governance: error.verdict,
        blocked: true,
      });
    }

    const statusCode = statusFromError ?? 500;

    return reply.code(statusCode).send({
      error: err.message || "Internal server error",
    });
  });

  app.get("/health/live", async () => {
    const started = performance.now();
    const { getVolumeDiskStats } = await import("./runtime/volume-disk-reclaim.js");
    const { env } = await import("./config/env.js");
    const { getTier0ControlPlaneSnapshot, recordTier0Request } = await import(
      "./runtime/tier0-control-plane.js"
    );
    const payload = {
      status: "ok" as const,
      brain: "online" as const,
      bootMode: process.env.EMPIRE_BOOT_MODE || "monolith",
      tier0Isolation: false,
      eventLoopLagMs: getRecentEventLoopLagMs(),
      eventLoopLagSmoothedMs: (await import("./runtime/event-loop-cooperative.js"))
        .getSmoothedEventLoopLagMs(),
      sqlite: getSqlitePersistStats(),
      admission: getAdmissionStats(),
      disk: getVolumeDiskStats(env.DATABASE_PATH),
      tier0: getTier0ControlPlaneSnapshot(),
      // Railway injects RAILWAY_GIT_COMMIT_SHA — use for deploy identity proof.
      deploy: {
        gitCommitSha:
          process.env.RAILWAY_GIT_COMMIT_SHA ||
          process.env.RAILWAY_GIT_COMMIT ||
          null,
        serviceName: process.env.RAILWAY_SERVICE_NAME || null,
        environmentName: process.env.RAILWAY_ENVIRONMENT_NAME || null,
        deploymentId: process.env.RAILWAY_DEPLOYMENT_ID || null,
      },
    };
    recordTier0Request({
      route: "health_live",
      durationMs: performance.now() - started,
      ok: true,
    });
    return payload;
  });

  // Process alive ≠ Grand King auth/Pillow ready. Railway admits traffic on
  // this endpoint; /health/live remains available for diagnostics.
  const redisRequired =
    env.NODE_ENV === "production" || process.env.EMPIRE_ROLE === "brain-worker";
  const pillowRequired = pillowEnabled || redisRequired;
  registerWorkerApplicationReadinessRoute(app, {
    assessAuthReadiness: async () => {
      const { assessAuthReadiness } = await import("./auth/auth-readiness.js");
      return assessAuthReadiness({ sessionStore });
    },
    probeRedisConnectivity: (timeoutMs) =>
      probeRedisSessionStore(brain.redis, timeoutMs),
    redisMode: brain.redisMode,
    redisRequired,
    pillowEnabled,
    pillowRequired,
    getPillowStatus: () => pillowHost.getStatus(),
  });

  app.get("/health/executive-continuity", async () => {
    const { getExecutiveContinuityHealth } = await import(
      "./runtime/executive-continuity-watchdog.js"
    );
    const continuity = getExecutiveContinuityHealth();
    return {
      status: continuity.healthy ? "ok" : "degraded",
      brain: "online",
      continuity,
      eventLoopLagMs: getRecentEventLoopLagMs(),
      sqlite: getSqlitePersistStats(),
    };
  });

  app.get("/health", async () => {
    // Never starve /health/live: skip expensive guardian integrity / Redis under lag.
    // Railway probes must use /health/live only (railway.toml).
    const lagMs = getRecentEventLoopLagMs();
    const skipHeavy = lagMs >= 80 || getSqlitePersistStats().flushInFlight;

    let guardianReport: Record<string, unknown> = { overall: "unknown" };
    if (skipHeavy) {
      guardianReport = {
        overall: "degraded",
        summary: `Heavy /health skipped (lag=${Math.round(lagMs)}ms or sqlite flush in flight) — use /health/live`,
        openRisks: 0,
      };
    } else {
      try {
        guardianReport = (await brain.guardian.checkHealth(brain, {
          recordRisks: false,
        })) as unknown as Record<string, unknown>;
      } catch (error) {
        guardianReport = {
          overall: "failed",
          summary: error instanceof Error ? error.message : "Health check failed",
        };
      }
    }

    let queueStats: Record<string, number> | { error: string; skipped?: boolean } = {};
    if (skipHeavy) {
      queueStats = { error: "skipped_under_lag", skipped: true };
    } else {
      try {
        queueStats = await brain.taskQueue.getStats();
      } catch (error) {
        queueStats = {
          error: error instanceof Error ? error.message : "Queue unavailable",
        };
      }
    }

    return {
      status: skipHeavy ? "degraded" : "ok",
      brain: "online",
      redisMode: brain.redisMode,
      eventLoopLagMs: lagMs,
      observability: getObservabilitySnapshot(),
      guardian: {
        overall: guardianReport.overall,
        summary: guardianReport.summary,
        openRisks: guardianReport.openRisks,
      },
      llmProviders: brain.llmRouter.listAvailable(),
      queue: queueStats,
      sqlite: getSqlitePersistStats(),
      admission: getAdmissionStats(),
    };
  });

  app.get(
    "/guardian/health",
    { preHandler: authenticate },
    async () => brain.guardian.checkHealth(brain),
  );

  app.get(
    "/guardian/risks",
    { preHandler: authenticate },
    async (request, reply) => {
      if (request.user!.role !== "admin") {
        return reply.code(403).send({ error: "Admin access required" });
      }
      return {
        risks: brain.guardian.listOpenRisks(),
        lastHealth: brain.guardian.getLastHealthReport(),
      };
    },
  );

  app.post(
    "/guardian/risks/:riskId/resolve",
    { preHandler: authenticate },
    async (request, reply) => {
      if (request.user!.role !== "admin") {
        return reply.code(403).send({ error: "Admin access required" });
      }
      const params = z.object({ riskId: z.string() }).parse(request.params);
      const resolved = brain.guardian.resolveRisk(params.riskId);
      if (!resolved) {
        return reply.code(404).send({ error: "Risk not found or already resolved" });
      }
      return { ok: true, riskId: params.riskId };
    },
  );

  app.get(
    "/metrics",
    { preHandler: authenticate },
    async (request, reply) => {
      if (request.user!.role !== "admin") {
        return reply.code(403).send({ error: "Admin access required" });
      }
      return getObservabilitySnapshot();
    },
  );

  await breathe();
  await registerAuthRoutes(app, {
    sessionStore,
    auditLogger: brain.auditLogger,
  });

  const routeDeps: EmpireRouteDeps = {
    app,
    authenticate,
    sessionStore,
    brain,
    pillowEnabled,
    pillowHost,
    eventStream,
    commerceAutomation,
  };

  // Both full and early-listen apps need the authenticated cockpit surface.
  await breathe();
  await registerCockpitCriticalRoutes(routeDeps);

  const withDrainedLocalAdmission = <T>(capture: () => T | Promise<T>, timeoutMs = 30_000): Promise<T> => {
    if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 30_000) {
      throw new Error("Local capture drain timeout invalid");
    }
    const deadline = performance.now() + timeoutMs;
    const remaining = () => {
      const value = Math.floor(deadline - performance.now());
      if (value < 1) throw new Error("Local capture drain deadline elapsed; no snapshot taken");
      return value;
    };
    // These commerce timers are separate from Pillow's boot task. Drain their
    // admitted runs and hold delayed/interval admissions through capture.
    return getPillowCommercePresaleAutomationServer().withPausedExecution(
      () => getPillowExecutiveLoopAutomationServer().withPausedExecution(
        () => captureHttpAdmission.withDrainedAdmission(
          () => brain.workerPool.withPausedProcessing(
            () => pillowBootTask.withPausedExecution(
              () => withLocalJsonAuthorityCapture(() => { remaining(); return capture(); }), remaining()), remaining()), remaining()), remaining()), remaining());
  };
  const withDrainedLocalSqliteCapture = <T>(shadow: SqliteShadowCeoRepository,
    captureAndVerify: () => T | Promise<T>, timeoutMs?: number): Promise<T> =>
    withDrainedLocalAdmission(() => withQuiescedBrainAndShadowCapture(
      getDatabase(), shadow, captureAndVerify), timeoutMs);
  const withDrainedLocalNativeCapture = <T>(shadow: SqliteShadowCeoRepository,
    captureAndVerify: () => T | Promise<T>, timeoutMs?: number): Promise<T> =>
    withDrainedLocalSqliteCapture(shadow, () => withExclusiveNativeMissionCapture(
      getActiveDatabasePath(), captureAndVerify), timeoutMs);
  const withDrainedSharedBrainNativeCapture = <T>(shadow: SqliteShadowCeoRepository,
    captureAndVerify: () => T | Promise<T>, timeoutMs?: number): Promise<T> => {
    if (!(brain.taskQueue instanceof TaskQueue)) {
      throw new Error("Shared Brain capture requires connected Redis; degraded queue cannot prove drain");
    }
    return brain.taskQueue.withPausedSharedProcessing(
      () => withDrainedLocalNativeCapture(shadow, captureAndVerify, timeoutMs), timeoutMs);
  };

  const withDrainedWork8LocalCapture = <T>(shadow: SqliteShadowCeoRepository,
    captureAndVerify: () => T | Promise<T>, timeoutMs = 30_000): Promise<T> => {
    const deadline = performance.now() + timeoutMs;
    return withDrainedWork8Background(() => {
      const remaining = Math.floor(deadline - performance.now());
      if (remaining < 1) throw new Error("Work8 local capture drain deadline elapsed; no snapshot taken");
      const root = process.env.RAILWAY_VOLUME_MOUNT_PATH;
      if (!root) throw new Error("Work8 domain capture requires explicit volume root");
      return withDrainedSharedBrainNativeCapture(shadow,
        () => withExclusiveWork8DomainCapture(root, captureAndVerify), remaining);
    }, timeoutMs);
  };

  const captureWork8Recovery = async (request:Work8RecoveryRequest,scope?:GeneratedCaptureScope):Promise<Work8RecoveryResult> => {
    if(request.requireComplete!==false) throw new Error("FULL_RUNTIME_CAPTURE_UNPROVEN");
    if (!(brain.taskQueue instanceof TaskQueue)) throw new Error("Recovery requires connected Redis");
    const queue=brain.taskQueue;
    const root=process.env.RAILWAY_VOLUME_MOUNT_PATH;
    if (!root) throw new Error("Recovery requires explicit volume root");
    if(scope)assertGeneratedCaptureScope(scope,request,root);
    let staged=false;
    try {
      // Load the temporary Shadow view only after every applicable admission
      // drain. Its read-only close happens inside those same boundaries on both
      // success and refusal; no stale SQL.js snapshot can flush after reopening.
      const result=await withPrimaryCaptureFence(()=>withDrainedWork8Background(()=>
        queue.withPausedSharedProcessing(()=>withDrainedLocalAdmission(()=>
          withExistingShadowCapture(getDatabase(),resolveShadowCeoDbPath(),shadow=>
            withExclusiveNativeMissionCapture(getActiveDatabasePath(),()=>
              withExclusiveWork8DomainCapture(root,async()=> {
                return pillowHost.withVisualMemoryRecoveryCapture(async (visualMemorySnapshot: Parameters<typeof captureWork8RecoveryInventory>[1]["visualMemorySnapshot"]) => {
                const captured=await captureWork8RecoveryInventory(request,{root,primaryPath:getActiveDatabasePath(),shadowPath:shadow.dbPath,visualMemorySnapshot},queue);
                staged=true;
                if(scope)await holdGeneratedCapture(scope,captured,{seal:finalizeWork8RecoveryInventory,verify:verifyWork8RecoveryInventory,invalidate:invalidateWork8RecoveryInventory});
                return captured;
                });
              })))))));
      finalizeWork8RecoveryInventory(result);
      verifyWork8RecoveryInventory(result);
      return result;
    } catch(error) {if(staged) invalidateWork8RecoveryInventory(request.destination);throw error;}
  };

  registerWork8RecoveryRoutes(app, {authenticate, founderEmail:env.FOUNDER_EMAIL,
    capture:request=>captureWork8Recovery(request)});

  if (earlyListen) {
    // Commerce proof path must be available without EMPIRE_ENABLE_EXTENSION_ROUTES.
    // Full REAL-module surface remains deferred behind finishRouteRegistration.
    await breathe();
    await registerCommerceCriticalRoutes(routeDeps);
    return {
      app,
      brain,
      shutdown: createEmpireShutdown({ app, brain, pillowEnabled, eventStream, stopBackgroundWork }),
      withDrainedHttpAdmission: (capture, timeoutMs) =>
        captureHttpAdmission.withDrainedAdmission(capture, timeoutMs),
      withDrainedLocalAdmission,
      withDrainedLocalSqliteCapture,
      withDrainedLocalNativeCapture,
      withDrainedSharedBrainNativeCapture,
      withDrainedWork8LocalCapture,
      captureWork8Recovery,
      finishRouteRegistration: () => registerEmpireExtensionRoutes(routeDeps),
    };
  }

  await breathe();
  await registerEmpireExtensionRoutes(routeDeps);

  return {
    app,
    brain,
    shutdown: createEmpireShutdown({ app, brain, pillowEnabled, eventStream, stopBackgroundWork }),
    withDrainedHttpAdmission: (capture, timeoutMs) =>
      captureHttpAdmission.withDrainedAdmission(capture, timeoutMs),
    withDrainedLocalAdmission,
    withDrainedLocalSqliteCapture,
    withDrainedLocalNativeCapture,
    withDrainedSharedBrainNativeCapture,
    withDrainedWork8LocalCapture,
    captureWork8Recovery,
  };
}

type EmpireRouteDeps = {
  app: FastifyInstance;
  authenticate: ReturnType<typeof createAuthMiddleware>;
  sessionStore: EmpireBrain["sessionStore"];
  brain: EmpireBrain;
  pillowEnabled: boolean;
  pillowHost: ReturnType<typeof getPillowHost>;
  eventStream: EventStreamHub;
  commerceAutomation: boolean;
};

function createEmpireShutdown(deps: {
  app: FastifyInstance;
  brain: EmpireBrain;
  pillowEnabled: boolean;
  eventStream: EventStreamHub;
  stopBackgroundWork: () => Promise<void>;
}) {
  const releaseFinance = retainProductionFinance();
  let shutdown: Promise<void> | undefined;
  return () => shutdown ??= (async () => {
    deps.eventStream.stop();
    await deps.stopBackgroundWork();
    await deps.app.close();
    if (deps.pillowEnabled) {
      await shutdownPillowHost();
    }
    await deps.brain.shutdown();
    releaseFinance();
  })();
}

