import type { InteractionTrackingEngine } from "../interaction-tracking-engine/engine.js";
import type { ContextAwarenessEngine } from "../context-awareness-engine/engine.js";
import {
  appendMemoryLog,
  getMemoryLogs,
  resetMemoryLogsForTesting,
} from "./memory-logging.js";
import { MemoryController } from "./memory-controller.js";
import {
  buildVisualMemoryConfiguration,
  type VisualMemoryConfiguration,
} from "./configuration.js";
import { VISUAL_MEMORY_SYSTEM_PATH } from "./paths.js";
import type {
  MemoryComparisonResult,
  VisualMemoryCockpitSnapshot,
  VisualMemoryRecord,
  VisualMemoryState,
} from "./types.js";

export interface VisualMemoryEngineOptions {
  configuration?: Partial<VisualMemoryConfiguration>;
  autoStart?: boolean;
}

/**
 * Visual Memory Engine (PILLOW-VME-001 / T1-08).
 * Stores and retrieves historical UI states from the EmpireAI interface.
 */
export class VisualMemoryEngine {
  private initializedAt: string | null = null;
  private readonly controller: MemoryController;
  private readonly reader: RepositoryReader;
  private autoStart: boolean;

  constructor(
    private bootstrap: EmpireBootstrapContext,
    visualCapture: VisualCaptureEngine,
    uiStateMapper: UiStateMapperEngine,
    componentRecognition: ComponentRecognitionEngine,
    layoutUnderstanding: LayoutUnderstandingEngine,
    navigationMapping: NavigationMappingEngine,
    interactionTracking: InteractionTrackingEngine,
    contextAwareness: ContextAwarenessEngine,
    options: VisualMemoryEngineOptions = {},
  ) {
    const config = buildVisualMemoryConfiguration(
      bootstrap.repositoryRoot,
      options.configuration,
    );
    this.controller = new MemoryController(
      bootstrap.repositoryRoot,
      visualCapture,
      uiStateMapper,
      componentRecognition,
      layoutUnderstanding,
      navigationMapping,
      interactionTracking,
      contextAwareness,
      config,
    );
    this.reader = new RepositoryReader(bootstrap.repositoryRoot);
    this.autoStart = options.autoStart ?? config.enabled;
  }

  async initialize(): Promise<VisualMemoryState> {
    const doc = await this.reader.readText(VISUAL_MEMORY_SYSTEM_PATH);
    if (!doc?.includes("Visual Memory")) {
      throw new Error(
        `${VISUAL_MEMORY_SYSTEM_PATH} missing — Visual Memory requires T1-08 system doc.`,
      );
    }
    await this.controller.initialize();
    this.initializedAt = new Date().toISOString();
    appendMemoryLog({
      event: "session_start",
      level: "info",
      details: "Visual Memory session initialized",
    });
    if (this.autoStart) {
      await this.controller.start();
    }
    return this.getState();
  }

  getState(): VisualMemoryState {
    if (!this.initializedAt) {
      throw new Error("Visual Memory Engine not initialized. Call initialize() first.");
    }
    const config = this.controller.getConfiguration();
    const performance = this.controller.getPerformance();
    const health = this.controller.getHealthMonitor().buildReport({
      config,
      status: this.controller.getStatus(),
      performance,
      consecutiveFailures: this.controller.getRecoveryManager().getConsecutiveFailures(),
      recoveryAttempts: this.controller.getRecoveryManager().getRecoveryAttempts(),
      backlogSize: this.controller.getMemoryBufferSize(),
    });

    return {
      engineVersion: "PILLOW-VME-001",
      missionId: "T1-08",
      status: this.controller.getStatus(),
      initializedAt: this.initializedAt,
      configuration: config,
      activeSession: this.controller.getSession(),
      latestRecord: this.controller.getLatestRecord(),
      health,
      performance,
    };
  }

  async startVisualMemory(): Promise<VisualMemoryState> {
    await this.controller.start();
    return this.getState();
  }

  stopVisualMemory(): VisualMemoryState {
    this.controller.stop();
    return this.getState();
  }

  pauseVisualMemory(): VisualMemoryState {
    this.controller.pause();
    return this.getState();
  }

  resumeVisualMemory(): VisualMemoryState {
    this.controller.resume();
    return this.getState();
  }

  withRecoverySnapshot<T>(capture:(snapshot: import("./memory-persistence-store.js").VisualMemoryRecoverySnapshot)=>Promise<T>):Promise<T> {
    return this.controller.withRecoverySnapshot(capture);
  }

  captureMemoryNow(): VisualMemoryRecord | null {
    return this.controller.captureNow();
  }

  getLatestRecord(): VisualMemoryRecord | null {
    return this.controller.getLatestRecord();
  }

  getRecentRecords(limit = 5): VisualMemoryRecord[] {
    return this.controller.getRecentRecords(limit);
  }

  retrieveRecent(limit?: number): VisualMemoryRecord[] {
    return this.controller.retrieveRecent(limit);
  }

  retrieveBySession(sessionId: string, limit?: number): VisualMemoryRecord[] {
    return this.controller.retrieveBySession(sessionId, limit);
  }

  retrieveByScreen(screenId: string, limit?: number): VisualMemoryRecord[] {
    return this.controller.retrieveByScreen(screenId, limit);
  }

  retrieveById(memoryRecordId: string): VisualMemoryRecord | null {
    return this.controller.retrieveById(memoryRecordId);
  }

  compareWithCurrent(memoryRecordId: string): MemoryComparisonResult | null {
    return this.controller.compareWithCurrent(memoryRecordId);
  }

  runRetentionCleanup(): VisualMemoryState {
    this.controller.runCleanup();
    return this.getState();
  }

  updateConfiguration(
    overrides: Partial<VisualMemoryConfiguration>,
  ): VisualMemoryState {
    const next = buildVisualMemoryConfiguration(this.bootstrap.repositoryRoot, {
      ...this.controller.getConfiguration(),
      ...overrides,
    });
    this.controller.updateConfiguration(next);
    return this.getState();
  }

  validateForSupervisorSync(): {
    valid: boolean;
    health: "healthy" | "degraded" | "blocked";
    readinessScore: number;
    notes: string[];
  } {
    const state = this.getState();
    const score = state.health.healthScore;
    return {
      valid: state.health.status !== "failed",
      health: score >= 75 ? "healthy" : score >= 50 ? "degraded" : "blocked",
      readinessScore: score,
      notes: [
        `Memory status: ${state.status}`,
        `Records stored: ${state.performance.successfulRecords}`,
        ...state.health.notes,
      ],
    };
  }

  getCockpitSnapshot(): VisualMemoryCockpitSnapshot {
    const state = this.getState();
    const latest = state.latestRecord;

    return {
      memoryStatus: state.status,
      healthStatus: state.health.status,
      recordsStored: state.performance.successfulRecords,
      latestScreenId: latest?.screenId ?? null,
      latestWorkflowContextId: latest?.sourceWorkflowContextId ?? null,
      storageUsedBytes: state.health.storageUsedBytes,
      retentionCategory: latest?.retentionCategory ?? null,
      confidenceScore: latest?.confidence ?? 0,
      recoveryAttempts: state.health.recoveryAttempts,
      recentLogs: getMemoryLogs(8, state.configuration).map((l) => `${l.event}: ${l.details}`),
    };
  }
}

export function createVisualMemoryEngine(
  bootstrap: EmpireBootstrapContext,
  visualCapture: VisualCaptureEngine,
  uiStateMapper: UiStateMapperEngine,
  componentRecognition: ComponentRecognitionEngine,
  layoutUnderstanding: LayoutUnderstandingEngine,
  navigationMapping: NavigationMappingEngine,
  interactionTracking: InteractionTrackingEngine,
  contextAwareness: ContextAwarenessEngine,
  options?: VisualMemoryEngineOptions,
): VisualMemoryEngine {
  return new VisualMemoryEngine(
    bootstrap,
    visualCapture,
    uiStateMapper,
    componentRecognition,
    layoutUnderstanding,
    navigationMapping,
    interactionTracking,
    contextAwareness,
    options,
  );
}

export function resetVisualMemoryForTesting(): void {
  resetMemoryLogsForTesting();
}

import { VisualMemoryCaptureBusyError } from "./recovery-lock.js";
/** T1-08 — Visual memory orchestration controller. */

import type { VisualCaptureEngine } from "../visual-capture-engine/engine.js";
import type { UiStateMapperEngine } from "../ui-state-mapper/engine.js";
import type { ComponentRecognitionEngine } from "../component-recognition-engine/engine.js";
import type { LayoutUnderstandingEngine } from "../layout-understanding-engine/engine.js";
import type { NavigationMappingEngine } from "../navigation-mapping-engine/engine.js";
import type { InteractionTrackingEngine } from "../interaction-tracking-engine/engine.js";
import type { ContextAwarenessEngine } from "../context-awareness-engine/engine.js";
import { appendMemoryLog } from "./memory-logging.js";
import { MemoryScheduler } from "./memory-scheduler.js";
import { MemoryBuffer } from "./memory-buffer.js";
import { HealthMonitor } from "./health-monitor.js";
import { RecoveryManager } from "./recovery-manager.js";
import { VisualMemoryManager } from "./visual-memory-manager.js";
import { MemoryCaptureEngine } from "./memory-capture-engine.js";
import { MemoryIndexer } from "./memory-indexer.js";
import { MemoryPersistenceStore } from "./memory-persistence-store.js";
import { MemoryRetrievalEngine } from "./memory-retrieval-engine.js";
import { MemoryComparisonEngine } from "./memory-comparison-engine.js";
import { MemoryRetentionManager } from "./memory-retention-manager.js";
import type { VisualMemoryConfiguration } from "./configuration.js";
import type {
  MemoryComparisonResult,
  MemoryPerformanceStats,
  MemoryStatus,
  VisualMemoryRecord,
} from "./types.js";

export class MemoryController {
  private config: VisualMemoryConfiguration;
  private status: MemoryStatus = "idle";
  private recordSequence = 0;
  private lastCaptureFingerprint = "";
  private performance: MemoryPerformanceStats = {
    totalRecords: 0,
    successfulRecords: 0,
    failedRecords: 0,
    maskedSensitiveFields: 0,
    retrievals: 0,
    comparisons: 0,
    cleanups: 0,
    averageStorageDurationMs: 0,
    peakStorageDurationMs: 0,
    skippedCaptures: 0,
    uptimeMs: 0,
  };

  private readonly sessionManager = new VisualMemoryManager();
  private readonly captureEngine = new MemoryCaptureEngine();
  private readonly memoryBuffer: MemoryBuffer;
  private readonly scheduler = new MemoryScheduler();
  private readonly healthMonitor = new HealthMonitor();
  private readonly recoveryManager = new RecoveryManager();
  private readonly indexer = new MemoryIndexer();
  private readonly persistenceStore: MemoryPersistenceStore;
  private retrievalEngine: MemoryRetrievalEngine;
  private readonly comparisonEngine = new MemoryComparisonEngine();
  private readonly retentionManager = new MemoryRetentionManager();

  private latestRecord: VisualMemoryRecord | null = null;
  private capturing = false;

  constructor(
    private repositoryRoot: string,
    private visualCapture: VisualCaptureEngine,
    private uiStateMapper: UiStateMapperEngine,
    private componentRecognition: ComponentRecognitionEngine,
    private layoutUnderstanding: LayoutUnderstandingEngine,
    private navigationMapping: NavigationMappingEngine,
    private interactionTracking: InteractionTrackingEngine,
    private contextAwareness: ContextAwarenessEngine,
    config: VisualMemoryConfiguration,
  ) {
    this.config = config;
    this.memoryBuffer = new MemoryBuffer(Math.min(50, config.maxRecords));
    this.persistenceStore = new MemoryPersistenceStore(repositoryRoot, config);
    this.retrievalEngine = new MemoryRetrievalEngine(this.indexer, this.persistenceStore, config);
  }

  getStatus(): MemoryStatus {
    return this.status;
  }

  getConfiguration(): VisualMemoryConfiguration {
    return { ...this.config };
  }

  updateConfiguration(config: VisualMemoryConfiguration): void {
    this.config = config;
    this.memoryBuffer.setLimit(Math.min(50, config.maxRecords));
    this.retrievalEngine = new MemoryRetrievalEngine(this.indexer, this.persistenceStore, config);
    if (this.scheduler.isRunning()) {
      this.stop();
      if (config.enabled) void this.start();
    }
  }

  async initialize(): Promise<void> {
    this.persistenceStore.initialize();
    this.indexer.setEntries(this.persistenceStore.loadIndex());
    const stats = this.persistenceStore.getStorageStats();
    this.healthMonitor.setStorageStats(stats.totalRecords, stats.usedBytes);
    appendMemoryLog({
      event: "engine_initialized",
      level: "info",
      details: `Visual Memory Engine initialized · ${stats.totalRecords} records loaded`,
    });
  }

  withRecoverySnapshot<T>(capture:(snapshot: import("./memory-persistence-store.js").VisualMemoryRecoverySnapshot)=>Promise<T>):Promise<T> {
    return this.persistenceStore.withRecoverySnapshot(capture);
  }

  async start(): Promise<void> {
    if (!this.config.enabled) {
      this.status = "idle";
      return;
    }
    if (this.scheduler.isRunning()) return;

    this.sessionManager.startSession();
    this.healthMonitor.markSessionStart();
    this.recoveryManager.reset();
    this.recordSequence = 0;
    this.lastCaptureFingerprint = "";
    this.status = "recording";

    appendMemoryLog({
      event: "memory_start",
      level: "info",
      details: "Visual memory session started",
    });

    this.scheduler.start(
      this.config,
      () => this.memoryTick(),
      () => this.runCleanup(),
    );
  }

  stop(): void {
    this.scheduler.stop();
    this.sessionManager.endSession("stopped");
    this.healthMonitor.markSessionEnd();
    this.status = "stopped";
    appendMemoryLog({ event: "memory_stop", level: "info", details: "Visual memory stopped" });
  }

  pause(): void {
    if (!this.scheduler.isRunning()) return;
    this.scheduler.pause();
    this.sessionManager.setStatus("paused");
    this.status = "paused";
    appendMemoryLog({ event: "memory_pause", level: "info", details: "Visual memory paused" });
  }

  resume(): void {
    if (!this.scheduler.isRunning()) return;
    this.scheduler.resume();
    this.sessionManager.setStatus("recording");
    this.status = "recording";
    appendMemoryLog({ event: "memory_resume", level: "info", details: "Visual memory resumed" });
  }

  getLatestRecord(): VisualMemoryRecord | null {
    return this.latestRecord;
  }

  getRecentRecords(limit = 5): VisualMemoryRecord[] {
    return this.memoryBuffer.getRecent(limit);
  }

  getSession() {
    return this.sessionManager.getSession();
  }

  getPerformance(): MemoryPerformanceStats {
    return { ...this.performance };
  }

  getHealthMonitor() {
    return this.healthMonitor;
  }

  getRecoveryManager() {
    return this.recoveryManager;
  }

  getMemoryBufferSize(): number {
    return this.memoryBuffer.size();
  }

  getIndexer() {
    return this.indexer;
  }

  getRetrievalEngine() {
    return this.retrievalEngine;
  }

  captureNow(): VisualMemoryRecord | null {
    if(this.persistenceStore.isRecoveryHeld())return null;
    const session = this.sessionManager.getSession();
    const sessionId = session?.sessionId ?? `vme-direct-${Date.now()}`;
    this.recordSequence += 1;
    const result = this.captureEngine.capture({
      sessionId,
      recordSequence: this.recordSequence,
      config: this.config,
      visualCapture: this.visualCapture,
      uiStateMapper: this.uiStateMapper,
      componentRecognition: this.componentRecognition,
      layoutUnderstanding: this.layoutUnderstanding,
      navigationMapping: this.navigationMapping,
      interactionTracking: this.interactionTracking,
      contextAwareness: this.contextAwareness,
      store: this.persistenceStore,
    });
    if (result.record && result.payload) {
      this.applyRecord(result.record, result.payload, result.componentIds, result.maskedSensitiveFields);
      return result.record;
    }
    return null;
  }

  retrieveRecent(limit?: number): VisualMemoryRecord[] {
    const records = this.retrievalEngine.retrieveRecent(limit);
    this.performance.retrievals += 1;
    return records;
  }

  retrieveBySession(sessionId: string, limit?: number): VisualMemoryRecord[] {
    this.performance.retrievals += 1;
    return this.retrievalEngine.retrieveBySession(sessionId, limit);
  }

  retrieveByScreen(screenId: string, limit?: number): VisualMemoryRecord[] {
    this.performance.retrievals += 1;
    return this.retrievalEngine.retrieveByScreen(screenId, limit);
  }

  retrieveById(memoryRecordId: string): VisualMemoryRecord | null {
    this.performance.retrievals += 1;
    return this.retrievalEngine.retrieveById(memoryRecordId);
  }

  compareWithCurrent(memoryRecordId: string): MemoryComparisonResult | null {
    const record = this.retrievalEngine.retrieveById(memoryRecordId);
    if (!record) return null;
    this.performance.comparisons += 1;
    return this.comparisonEngine.compare(record, {
      navigationMapping: this.navigationMapping,
      layoutUnderstanding: this.layoutUnderstanding,
      componentRecognition: this.componentRecognition,
      interactionTracking: this.interactionTracking,
    });
  }

  runCleanup(): void {
    if(this.persistenceStore.isRecoveryHeld())return;
    let removed: number;
    try { removed = this.persistenceStore.withWriteTransaction(()=>this.retentionManager.applyRetention(
      this.indexer,
      this.persistenceStore,
      this.config,
    )); } catch(error) {
      // Another updated process owns capture; this timer simply skips its tick.
      // Storage corruption, unsafe roots and other failures remain visible.
      if(error instanceof VisualMemoryCaptureBusyError)return;
      throw error;
    }
    if (removed > 0) {
      this.performance.cleanups += 1;
      const stats = this.persistenceStore.getStorageStats();
      this.healthMonitor.setStorageStats(stats.totalRecords, stats.usedBytes);
    }
  }

  resetForTesting(): void {
    this.persistenceStore.resetForTesting();
    this.indexer.setEntries([]);
  }

  private applyRecord(
    record: VisualMemoryRecord,
    payload: import("./memory-persistence-store.js").StoredMemoryPayload,
    componentIds: string[],
    maskedCount: number,
  ): void {
    const started = Date.now();
    try {
      const bytes = this.persistenceStore.withWriteTransaction(()=>{
        const written=this.persistenceStore.write(payload);
        this.indexer.index(record, componentIds);
        this.persistenceStore.saveIndex(this.indexer.getAll());
        return written;
      });
      const duration = Date.now() - started;

      this.latestRecord = record;
      this.memoryBuffer.push(record);
      this.sessionManager.recordStored(true, record.screenId);
      this.recoveryManager.recordSuccess();
      this.performance.successfulRecords += 1;
      this.performance.totalRecords += 1;
      this.performance.maskedSensitiveFields += maskedCount;
      this.performance.averageStorageDurationMs = Math.round(
        (this.performance.averageStorageDurationMs * (this.performance.successfulRecords - 1) + duration) /
          this.performance.successfulRecords,
      );
      if (duration > this.performance.peakStorageDurationMs) {
        this.performance.peakStorageDurationMs = duration;
      }
      this.healthMonitor.recordStorage(duration, true, bytes);
      const stats = this.persistenceStore.getStorageStats();
      this.healthMonitor.setStorageStats(stats.totalRecords, stats.usedBytes);
    } catch (error) {
      const message = error instanceof Error ? error.message : "Storage failed";
      this.sessionManager.recordStored(false, null);
      this.performance.failedRecords += 1;
      this.healthMonitor.recordStorage(0, false);
      throw new Error(message);
    }
  }

  private fingerprint(): string {
    const uiState = this.uiStateMapper.getLatestState();
    const graph = this.navigationMapping.getLatestGraph();
    const layout = this.layoutUnderstanding.getLatestLayout();
    const context = this.contextAwareness.getLatestContext();
    const events = this.interactionTracking.getRecentEvents(3);
    return [
      uiState?.metadata.stateId ?? "",
      graph?.metadata.graphId ?? "",
      layout?.metadata.layoutId ?? "",
      context?.contextId ?? "",
      events.map((e) => e.eventId).join(","),
    ].join("|");
  }

  private async memoryTick(): Promise<void> {
    if(this.persistenceStore.isRecoveryHeld())return;
    if (this.capturing) {
      this.performance.skippedCaptures += 1;
      return;
    }
    this.capturing = true;
    try {
      const session = this.sessionManager.getSession();
      if (!session) {
        this.status = "failed";
        return;
      }

      const fp = this.fingerprint();
      if (fp === this.lastCaptureFingerprint && fp !== "") {
        return;
      }

      this.recordSequence += 1;
      const result = this.captureEngine.capture({
        sessionId: session.sessionId,
        recordSequence: this.recordSequence,
        config: this.config,
        visualCapture: this.visualCapture,
        uiStateMapper: this.uiStateMapper,
        componentRecognition: this.componentRecognition,
        layoutUnderstanding: this.layoutUnderstanding,
        navigationMapping: this.navigationMapping,
        interactionTracking: this.interactionTracking,
        contextAwareness: this.contextAwareness,
        store: this.persistenceStore,
      });

      if (result.record && result.payload) {
        this.applyRecord(
          result.record,
          result.payload,
          result.componentIds,
          result.maskedSensitiveFields,
        );
        this.lastCaptureFingerprint = fp;
        this.status = "recording";
      } else {
        this.sessionManager.recordStored(false, null);
        this.performance.failedRecords += 1;
        this.healthMonitor.recordStorage(0, false);
        const shouldRecover = this.recoveryManager.recordFailure(
          result.error ?? "Unknown memory capture error",
          this.config,
        );
        if (shouldRecover) {
          this.status = "recovering";
          this.status = "recording";
        } else if (this.recoveryManager.getConsecutiveFailures() >= this.config.maxRetryAttempts) {
          this.status = "failed";
          appendMemoryLog({
            event: "memory_failed",
            level: "error",
            details: result.error ?? "Max retries exceeded",
          });
        }
      }
    } finally {
      this.capturing = false;
    }
  }
}

/** T1-08 — Persistent storage for visual memory records. */

import { mkdirSync, readFileSync, writeFileSync, existsSync, unlinkSync, statSync, lstatSync, realpathSync, readdirSync } from "node:fs";
import { join, resolve } from "node:path";
import { acquireVisualMemoryLock } from "./recovery-lock.js";
import { appendMemoryLog } from "./memory-logging.js";
import type { VisualMemoryConfiguration } from "./configuration.js";
import type { MemoryIndexEntry, VisualMemoryRecord } from "./types.js";

export type StoredMemoryPayload = {
  record: VisualMemoryRecord;
  uiStateHistory?: unknown;
  componentHistory?: unknown;
  layoutHistory?: unknown;
  navigationHistory?: unknown;
  interactionHistory?: unknown;
  workflowContextHistory?: unknown;
};

export type VisualMemoryRecoverySnapshot = {schema:"VISUAL_MEMORY_INSPECTION_V1";sourceStoragePath:string;operationalRestoreAvailable:false;files:Array<{path:string;bytes:string;mode:number}>};

export class MemoryPersistenceStore {
  private recoveryHeld = false;
  private writeDepth = 0;
  withWriteTransaction<T>(write:()=>T):T {
    this.assertWritable();
    if(this.config.storageBackend==='memory'||this.writeDepth>0)return write();
    const release=acquireVisualMemoryLock(this.getStorageDir());
    this.writeDepth++;
    try{return write();}finally{this.writeDepth--;release();}
  }
  isRecoveryHeld(): boolean { return this.recoveryHeld; }
  private assertWritable(): void { if (this.recoveryHeld) throw new Error("VISUAL_MEMORY_RECOVERY_HELD"); }
  /** Local single-event-loop writer exclusion only; no global topology claim. */
  async withRecoverySnapshot<T>(capture:(snapshot:VisualMemoryRecoverySnapshot)=>Promise<T>):Promise<T> {
    if(this.recoveryHeld) throw new Error("VISUAL_MEMORY_RECOVERY_ALREADY_HELD");
    if(this.config.storageBackend!=="file") throw new Error("VISUAL_MEMORY_FILE_CAPTURE_REQUIRED");
    const release=acquireVisualMemoryLock(this.getStorageDir());
    this.recoveryHeld=true;
    try {
      const root=resolve(this.getStorageDir());
      if(realpathSync(root)!==root||!lstatSync(root).isDirectory())throw new Error("VISUAL_MEMORY_ROOT_UNSAFE");
      const entries=readdirSync(root).sort();
      if(entries.some(x=>x!=="index.json"&&x!=="records")||!entries.includes("records"))throw new Error("VISUAL_MEMORY_INVENTORY_UNKNOWN");
      const records=join(root,"records");
      if(realpathSync(records)!==records||!lstatSync(records).isDirectory())throw new Error("VISUAL_MEMORY_RECORDS_UNSAFE");
      const names=readdirSync(records).sort();
      if(names.length>10000||names.some(x=>!/^[-a-zA-Z0-9_.]+\.json$/.test(x)))throw new Error("VISUAL_MEMORY_RECORD_NAMES_INVALID");
      let total=0;const files:Array<{path:string;bytes:string;mode:number}>=[];
      for(const name of [...(entries.includes("index.json")?["index.json"]:[]),...names.map(x=>"records/"+x)]) {
        const filename=join(root,name),st=lstatSync(filename);
        if(!st.isFile()||st.nlink!==1||realpathSync(filename)!==filename)throw new Error("VISUAL_MEMORY_FILE_UNSAFE");
        total+=st.size;if(total>33554432)throw new Error("VISUAL_MEMORY_CAPTURE_SIZE");
        const bytes=readFileSync(filename);JSON.parse(bytes.toString("utf8"));
        files.push({path:name,bytes:bytes.toString("base64"),mode:st.mode&0o777});
      }
      return await capture({schema:"VISUAL_MEMORY_INSPECTION_V1",sourceStoragePath:root,operationalRestoreAvailable:false,files});
    } finally {try{release();}finally{this.recoveryHeld=false;}}
  }

  private memoryRecords = new Map<string, StoredMemoryPayload>();
  private memoryIndex: MemoryIndexEntry[] = [];

  constructor(
    private repositoryRoot: string,
    private config: VisualMemoryConfiguration,
  ) {}

  getStorageDir(): string {
    return join(this.repositoryRoot, this.config.storageRoot);
  }

  getRecordsDir(): string {
    return join(this.getStorageDir(), "records");
  }

  getIndexPath(): string {
    return join(this.getStorageDir(), "index.json");
  }

  getRecordPath(memoryRecordId: string): string {
    return join(this.getRecordsDir(), `${memoryRecordId}.json`);
  }

  initialize(): void {
    if(this.config.storageBackend!=="memory")mkdirSync(resolve(this.getStorageDir(),".."),{recursive:true});
    return this.withWriteTransaction(()=>this.initializeAdmitted());
  }

  private initializeAdmitted(): void {
    this.assertWritable();
    if (this.config.storageBackend === "memory") return;
    const dir = this.getStorageDir();
    const recordsDir = this.getRecordsDir();
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    if (!existsSync(recordsDir)) mkdirSync(recordsDir, { recursive: true });
    this.loadIndex();
  }

  loadIndex(): MemoryIndexEntry[] {
    if (this.config.storageBackend === "memory") return this.memoryIndex;
    const indexPath = this.getIndexPath();
    if (!existsSync(indexPath)) return [];
    try {
      const data = JSON.parse(readFileSync(indexPath, "utf8")) as { entries?: MemoryIndexEntry[] };
      this.memoryIndex = data.entries ?? [];
      return this.memoryIndex.map((e) => ({ ...e, componentIds: [...e.componentIds] }));
    } catch {
      appendMemoryLog({
        event: "storage_failure",
        level: "warn",
        details: "Failed to load memory index — starting fresh",
      });
      return [];
    }
  }

  saveIndex(entries: MemoryIndexEntry[]): void {
    return this.withWriteTransaction(()=>this.saveIndexAdmitted(entries));
  }

  private saveIndexAdmitted(entries: MemoryIndexEntry[]): void {
    this.assertWritable();
    this.memoryIndex = entries.map((e) => ({ ...e, componentIds: [...e.componentIds] }));
    if (this.config.storageBackend === "memory") return;
    try {
      writeFileSync(
        this.getIndexPath(),
        JSON.stringify({ version: "1.0.0", entries: this.memoryIndex }, null, 2),
        "utf8",
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : "Index save failed";
      appendMemoryLog({ event: "storage_failure", level: "error", details: message });
      throw error;
    }
  }

  write(payload: StoredMemoryPayload): number {
    return this.withWriteTransaction(()=>this.writeAdmitted(payload));
  }

  private writeAdmitted(payload: StoredMemoryPayload): number {
    this.assertWritable();
    const recordPath = this.getRecordPath(payload.record.memoryRecordId);
    const json = JSON.stringify(payload, null, 2);
    const bytes = Buffer.byteLength(json, "utf8");

    if (this.config.storageBackend === "memory") {
      this.memoryRecords.set(payload.record.memoryRecordId, payload);
      return bytes;
    }

    try {
      writeFileSync(recordPath, json, "utf8");
      return bytes;
    } catch (error) {
      const message = error instanceof Error ? error.message : "Record write failed";
      appendMemoryLog({ event: "storage_failure", level: "error", details: message });
      throw error;
    }
  }

  read(memoryRecordId: string): StoredMemoryPayload | null {
    if (this.config.storageBackend === "memory") {
      const payload = this.memoryRecords.get(memoryRecordId);
      return payload ? structuredClone(payload) : null;
    }
    const recordPath = this.getRecordPath(memoryRecordId);
    if (!existsSync(recordPath)) return null;
    try {
      return JSON.parse(readFileSync(recordPath, "utf8")) as StoredMemoryPayload;
    } catch {
      appendMemoryLog({
        event: "storage_failure",
        level: "warn",
        details: `Corrupted record ${memoryRecordId}`,
      });
      return null;
    }
  }

  delete(memoryRecordId: string): void {
    return this.withWriteTransaction(()=>this.deleteAdmitted(memoryRecordId));
  }

  private deleteAdmitted(memoryRecordId: string): void {
    this.assertWritable();
    if (this.config.storageBackend === "memory") {
      this.memoryRecords.delete(memoryRecordId);
      return;
    }
    const recordPath = this.getRecordPath(memoryRecordId);
    if (existsSync(recordPath)) {
      try {
        unlinkSync(recordPath);
      } catch (error) {
        const message = error instanceof Error ? error.message : "Record delete failed";
        appendMemoryLog({ event: "storage_failure", level: "warn", details: message });
      }
    }
  }

  getStorageStats(): { totalRecords: number; usedBytes: number } {
    if (this.config.storageBackend === "memory") {
      let usedBytes = 0;
      for (const payload of this.memoryRecords.values()) {
        usedBytes += Buffer.byteLength(JSON.stringify(payload), "utf8");
      }
      return { totalRecords: this.memoryIndex.length, usedBytes };
    }

    let usedBytes = 0;
    for (const entry of this.memoryIndex) {
      const path = this.getRecordPath(entry.memoryRecordId);
      if (existsSync(path)) {
        try {
          usedBytes += statSync(path).size;
        } catch {
          // skip unreadable files
        }
      }
    }
    return { totalRecords: this.memoryIndex.length, usedBytes };
  }

  resetForTesting(): void {
    this.memoryRecords.clear();
    this.memoryIndex = [];
  }
}

import fs from 'node:fs';
import path from 'node:path';
export class VisualMemoryCaptureBusyError extends Error { constructor(){super("VISUAL_MEMORY_SHARED_CAPTURE_BUSY");this.name="VisualMemoryCaptureBusyError";} }
/** Stable exclusion for updated cooperating processes. Never steal stale locks. */
export function acquireVisualMemoryLock(storageRoot:string):()=>void {
 const root=path.resolve(storageRoot),parent=path.dirname(root);
 if(fs.realpathSync(parent)!==parent)throw Error('VISUAL_MEMORY_LOCK_PATH_UNSAFE');
 try{const current=fs.lstatSync(root);if(!current.isDirectory()||current.isSymbolicLink()||fs.realpathSync(root)!==root)throw Error('VISUAL_MEMORY_LOCK_ROOT_UNSAFE');}
 catch(error){if((error as NodeJS.ErrnoException).code!=='ENOENT')throw error;}
 const lock=root+'.capture-write-lock';
 try{fs.mkdirSync(lock,{mode:0o700});}catch(error){if((error as NodeJS.ErrnoException).code==='EEXIST')throw new VisualMemoryCaptureBusyError();throw error;}
 const identity=fs.lstatSync(lock);let released=false;
 return ()=>{if(released)return;const current=fs.lstatSync(lock);if(!current.isDirectory()||current.isSymbolicLink()||current.dev!==identity.dev||current.ino!==identity.ino)throw Error('VISUAL_MEMORY_LOCK_IDENTITY_CHANGED');fs.rmdirSync(lock);released=true;};
}
